// Explicit rules (hand-written, the mutation-sensitive integer details; the constants follow from the original instructions and the synthetic bytes of
// the generated table: the bank anims read synthetic(window) + displacement, the tables read synthetic(table + index)).
const char*CARRY_ERROR="objects fr14 caller requires known carry";
const char*ROM_ERROR="missing or ambiguous physical program bus ROM byte";
State carried(std::uint32_t pc,unsigned int c){State s=st(pc);s.carry=carry_of(c);return s;}
std::uint32_t bank_long(std::uint32_t window,std::uint32_t displacement){return synthetic(synthetic(window,4)+displacement,4);}
// ASR.L #4 reference (sign fill, written out bit by bit for the rules only).
std::uint32_t asr4(std::uint32_t v){std::uint32_t r=v;for(unsigned int i=0;i<4;++i)r=(r>>1)|(r&0x80000000U);return r;}
